WITH history AS (SELECT DATE_TRUNC('DAY', "EVENT_DATE") AS period, COUNT(*) AS cnt FROM "FAKE_PROJECT"."DATASET"."ORDERS" WHERE "EVENT_DATE" >= '2026-05-01'::DATE - INTERVAL '28 DAY' AND "EVENT_DATE" < '2026-05-01'::DATE GROUP BY period), medians AS (SELECT PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY cnt) AS median FROM history) SELECT (SELECT median FROM medians) AS median, PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY ABS(cnt - (SELECT median FROM medians))) AS mad, COUNT(*) AS n FROM history